import json,re,collections,statistics
from fractions import Fraction
pat=re.compile(r'\\boxed\s*\{')
def boxes(s):
 out=[]
 for m in pat.finditer(s):
  a=m.end(); n=1;i=a
  while i<len(s) and n:
   if s[i]=='{':n+=1
   elif s[i]=='}':n-=1
   i+=1
  if n==0:out.append(s[a:i-1])
 return out

def num(s):
 s=s.replace(',','').replace('\\$','').replace('$','').replace('\\,','').replace('\\!','').replace('\\%','').strip()
 s=re.sub(r'\\(?:text|mathrm)\{[^{}]*\}','',s).strip()
 s=re.sub(r'\\(?:d|t)?frac\{([-+\d.]+)\}\{([-+\d.]+)\}',r'(\1)/(\2)',s)
 if re.fullmatch(r'[-+]?\d+(?:\.\d+)?',s):return Fraction(s)
 if re.fullmatch(r'\([-+\d.]+\)/\([-+\d.]+\)',s):
  a,b=s.split('/');return Fraction(a.strip('()'))/Fraction(b.strip('()'))
 return None
for dr,steps in [('val_generations',[0,50,100]),('rollouts',[1,50,100])]:
 for step in steps:
  rr=[json.loads(s) for s in open(f'results/run100/{dr}/{step}.jsonl')]
  counts=collections.Counter();examples=[]
  for i,r in enumerate(rr):
   bs=boxes(r['output']); gold=num(r['gts']); last=num(bs[-1]) if bs else None
   counts['positive']+=r['score']==1
   counts['multi_box']+=len(bs)>1
   if last is not None:
    counts['simple_numeric_final_box']+=1
    counts['simple_numeric_correct_final_box']+=last==gold
    if r['score']==1 and last!=gold:
     counts['positive_wrong_numeric_final_box']+=1
     examples.append((i,r['gts'],bs,r['output'][-1000:]))
   if r['score']==1 and not bs:counts['positive_no_box']+=1
   if r['score']==0 and last==gold:counts['negative_correct_numeric_final_box']+=1
  print(dr,step,dict(counts))
  for x in examples[:3]:print('example',x)
